import {ReviewView} from './review-view.mjs';
import {archiveExecution,identityOf,sameIdentity,currentExecution,planSummary} from './review-core.mjs';
import {MaterialIntake} from './material-intake.mjs';
import {dimensions} from './assessment-core.mjs';
import {reproductionState,reproductionStatuses,auditCounts,reproductionSummary,validateReproductionReport,startBlocker,parseEvidenceArchive} from './reproduction-core.mjs';
const verdicts={within_tolerance:'参考均值在容差内',outside_tolerance:'超出参考容差',pass:'检查符合',fail:'发现矛盾',unknown:'缺少证据',review_required:'需人工核对',supported:'获得支持',not_supported:'未获支持',inconclusive:'证据不足'};
const number=v=>typeof v==='number'&&Number.isFinite(v)?v.toFixed(6).replace(/\.?0+$/,''):'未测';
export class ReproductionWorkspace{
 constructor(intake){this.i=intake;this.materials=new MaterialIntake(this);this.dimension='scope';this.error='';this.busy=false;this.timer=null;this.caseReport=null;this.inspecting=false;this.panel='prepare';this.review=new ReviewView(this);this.registry=[];this.registrySelection=null;this.registryError='';}
 render(p){const s=reproductionState(p),e=x=>this.i.esc(x),counts=auditCounts(s.audit);return `<section class="reproduction-workspace"><div class="assessment-intro"><div><h2>完整实验工作区</h2><p>材料版本、冻结计划与运行证据使用同一份身份记录。</p></div><div class="source-actions"><button class="btn" data-reproduction="public-case">${this.caseReport?'返回当前项目':'公开 CPU 案例'}</button><label class="btn">导入归档报告<input class="sr-only" type="file" accept=".json,application/json" data-reproduction-report></label></div></div>${this.error?`<p class="error-box" role="alert">${e(this.error)}</p>`:''}${this.caseReport?`<section class="public-case-evidence"><h2>LIBLINEAR · 独立公开案例</h2><p class="small-note">CI 归档证据独立于当前项目；不写入当前论文的评估结果。</p>${this.report(this.caseReport,{source:'public_case'},reproductionSummary(this.caseReport),e)}</section>`:`<div class="workflow-tabs" role="group" aria-label="完整实验流程">${[['prepare','材料与计划'],['check',`核验记录${s.audit?' · '+counts.fail+' 项矛盾':''}`],['launch','执行配置'],['history','结果与历史']].map(([id,label])=>`<button class="${this.panel===id?'active':''}" data-full-panel="${id}" aria-pressed="${this.panel===id}">${label}</button>`).join('')}</div>${this.panel==='prepare'?`${this.materials.render(p)}<details class="reproduction-plan" ${s.material_bundle?'':'open'}><summary>使用已有的本地实验计划</summary><div class="field"><label for="reproduction-plan-path">工作区中的 plan.json 路径</label><div class="joined-field"><input id="reproduction-plan-path" data-reproduction-plan value="${e(s.plan_path)}" placeholder="runs/liblinear-input/plan.json"><button class="btn" data-reproduction="audit" ${this.busy||this.i.h.mode()!=='runtime'?'disabled':''}>${this.busy?'正在核验…':'核验实际材料'}</button></div></div><p class="small-note">examples/reproduction_smoke/plan.json 提供工程样例。计划中的阶段命令与数据来源由复现者确认。</p></details>`:this.panel==='check'?this.auditPanel(s,e):this.panel==='launch'?this.launchPanel(s,e):this.historyPanel(p,e)}`}</section>`;}
 auditPanel(s,e){const a=s.audit;if(!a)return '<section class="assessment-empty"><h3>尚无当前版本的核验记录</h3><p>导入 PDF、代码 ZIP 和实验计划，绑定后核验实际文件。</p><button class="btn" data-full-panel="prepare">准备材料与计划</button></section>';const counts=auditCounts(a);return `${this.coverage(a,e)}<section class="reproduction-audit"><div class="section-heading"><h3>八项材料核验</h3><button class="btn text" data-reproduction="export-audit">导出核验记录</button></div><p>${counts.pass} 项符合 · ${counts.fail} 项矛盾 · ${counts.unknown} 项缺证据 · ${counts.review_required} 项需人工核对</p><div class="audit-review-layout"><div class="criteria-index">${dimensions.map(([id,label])=>{const rows=a.checks.filter(c=>c.dimension===id);return `<button class="criterion-item ${this.dimension===id?'selected':''}" data-reproduction-dimension="${id}" aria-pressed="${this.dimension===id}"><strong>${label}</strong><span>${rows.filter(c=>c.status!=='pass').length} 项待关注</span></button>`;}).join('')}</div><div class="audit-evidence-list">${a.checks.filter(c=>c.dimension===this.dimension).map(c=>`<details><summary><strong>${e(verdicts[c.status]||c.status)}</strong> ${e(c.code)}</summary><p>${e(c.detail)}</p><pre>${e(JSON.stringify(c.evidence,null,2))}</pre></details>`).join('')||'<p>该维度无记录。</p>'}</div></div><button class="btn" data-full-panel="launch">核对实际执行配置</button></section>`;}
 launchPanel(s,e){const preview=s.audit?.execution_preview,blocked=startBlocker(s,this.i.h.mode()),sum=planSummary(preview);if(!preview)return '<section class="assessment-empty"><h3>尚无核验过的执行配置</h3><p>实际配置从本机审计接口读取。服务器说明与短时核查预算不替代完整实验计划。</p><button class="btn" data-full-panel="prepare">读取实验计划</button></section>';const r=preview.resources;return `<section class="execution-confirmation"><div class="section-heading"><h3>启动前确认冻结计划</h3><span>计划 <code>${e(preview.plan_sha256.slice(0,12))}</code></span></div><p>以下配置来自本次核验的计划，启动时由服务器再次检查版本。</p><dl class="execution-budget"><div><dt>运行矩阵</dt><dd>${sum.runs} 次 / ${sum.stages} 个阶段</dd></div><div><dt>总时间上限</dt><dd>${e(r.max_seconds??3600)} 秒</dd></div><div><dt>每容器 CPU / 内存</dt><dd>${e(r.cpus??1)} 核 / ${((r.memory_bytes??2147483648)/1024**3).toFixed(1)} GiB</dd></div><div><dt>GPU 设备</dt><dd>${e(r.gpu_devices?.join(', ')||'未启用')}</dd></div><div><dt>声明单价</dt><dd>${r.price_per_hour_usd==null?'未知':'$'+r.price_per_hour_usd+' / 小时'}</dd></div><div><dt>项目磁盘上限</dt><dd>${r.project_disk_limit_bytes==null?'未声明':(r.project_disk_limit_bytes/1024**3).toFixed(1)+' GiB'}</dd></div></dl><p class="small-note">容器限制与主机可用资源不同；构建及采样范围见实际报告。单价由用户声明，不含下载、人工、网络和存储费用。短时核查预算单独配置。</p>${preview.experiments.map(x=>`<details class="plan-experiment" open><summary>${e(x.id)} · ${x.seeds.length} 个种子 × ${x.variants.length} 个方法</summary><p>种子 ${x.seeds.join('、')} · 指标 ${e(x.metric?.key||'未声明')}</p><p>${x.variants.map(v=>e(v.id)+'（'+e(v.role)+'）').join(' / ')}</p><ol class="plan-stages">${x.stages.map(st=>`<li><strong>${e(st.id)}</strong><span>${e(st.kind)} · 前置 ${e(st.needs?.join(', ')||'无')}</span><pre>${e(JSON.stringify(st.argv))}</pre><p class="small-note">输入 ${e(st.inputs?.join(', ')||'未声明')} → 输出 ${e(st.outputs?.join(', ')||'未声明')}</p></li>`).join('')}</ol></details>`).join('')}<details><summary>环境构建与完整资源声明</summary><pre>${e(JSON.stringify({environment:preview.environment,resources:r},null,2))}</pre></details><label class="check-label launch-consent"><input type="checkbox" data-execution-confirm ${s.confirmed_plan===preview.plan_sha256?'checked':''}>我已核对这份计划的命令、运行矩阵与资源上限</label><div class="source-actions"><button class="btn primary" data-reproduction="start" ${this.busy||blocked||s.confirmed_plan!==preview.plan_sha256?'disabled':''}>启动完整实验</button>${s.job&&['queued','running'].includes(s.job.status)?'<button class="btn" data-reproduction="cancel">停止实验</button>':''}</div>${blocked?`<p class="small-note">${e(blocked)}</p>`:''}</section>`;}
 historyPanel(p,e){const s=reproductionState(p),current=currentExecution(p);return `<section class="execution-history"><div class="section-heading"><h3>当前版本的实验结果</h3>${current?.job?'<button class="btn" data-reproduction="refresh">刷新任务与报告</button>':''}</div>${current?.job?`<p>${reproductionStatuses[current.job.status]} · ${e(current.job.id.slice(0,12))}${current.job.error?' · '+e(current.job.error):''}</p>`:''}${current?.report?this.report(current.report,current,reproductionSummary(current.report),e):'<p class="assessment-empty">当前材料版本没有完整实验报告。历史运行和导入的归档独立保留。</p>'}<h3>历史与外部归档</h3>${(s.history||[]).map((entry,index)=>`<details class="history-entry"><summary>${entry.source==='uploaded'?'导入归档':reproductionStatuses[entry.job?.status||entry.report?.status]||'历史记录'} · ${e(entry.id?.slice(0,12)||'无运行 ID')}<span>${e(entry.reason||'历史材料版本')}</span></summary><p class="small-note">计划 ${e(entry.report?.plan_sha256?.slice(0,12)||entry.job?.plan_sha256?.slice(0,12)||'未知')} · ${e(entry.archived_at?.slice(0,16)||'归档时间未知')}</p>${entry.report?this.report(entry.report,{source:entry.source,job:entry.job,reviews:entry.reviews},reproductionSummary(entry.report),e):`<button class="btn" data-history-refresh="${index}">读取历史任务证据</button>`}</details>`).join('')||'<p class="small-note">暂无历史记录。</p>'}</section>`;}
 report(r,s,sum,e){return this.review.render(r,s,e);}

 legacyReport(r,s,sum,e){return `<div class="reproduction-report"><div class="assessment-intro"><div><h3>${s.source==='runtime'?'本地运行时返回的证据':s.source==='public_case'?'公开案例归档证据':'导入的执行记录'}</h3><p>${reproductionStatuses[r.status]} · ${sum.completed} / ${sum.expected??'未知'} 次计划运行完成 · ${sum.stages} 个已记录阶段</p></div><button class="btn text" data-reproduction="${s.source==='public_case'?'export-case':'export-report'}">导出当前报告</button></div>${s.source==='uploaded'?'<p class="info-strip">此报告由用户导入；网页展示其中的记录，尚未连接原执行主机核验来源。</p>':s.source==='public_case'?`<p class="info-strip">作者版本和划分偏差已保留；当前记录不覆盖 Figure 1 与 rcv1；额外控制没有进行最优参数搜索，不验证论文的效率结论。<a href="${e(r.provenance?.workflow_url||'https://github.com/Gump111458785/ArtiCheck/actions/workflows/reproduce-liblinear.yml')}" target="_blank" rel="noopener">查看 CI 来源</a></p>`:''}<dl class="evaluation-facts"><div><dt>实际耗时</dt><dd>${typeof r.elapsed_seconds==='number'?r.elapsed_seconds.toFixed(2)+' 秒':'未测'}</dd></div><div><dt>环境重建</dt><dd>${r.levels?.environment_rebuilt?'已记录构建及镜像内验证':'未验证'}</dd></div><div><dt>子进程峰值 RSS</dt><dd>${typeof r.measurement?.max_child_rss_bytes==='number'?(r.measurement.max_child_rss_bytes/1024**2).toFixed(1)+' MiB':'未测'}</dd></div><div><dt>GPU 容器进程显存采样峰值</dt><dd>${r.measurement?.gpu_peak_memory_bytes==null?'未测':(r.measurement.gpu_peak_memory_bytes/1024**2).toFixed(1)+' MiB'}</dd></div><div><dt>计算费用估计</dt><dd>${r.cost?.compute_estimate_usd==null?'单价未知，无法估计':'$'+r.cost.compute_estimate_usd.toFixed(6)}</dd></div></dl>${this.levels(r,e)}${this.environmentEvidence(r,e)}${r.errors?.length?`<p class="error-box">${e(r.errors.join('；'))}</p>`:''}<p class="small-note table-scroll-hint">在表格内横向滚动查看全部指标。</p><div class="scroll-table"><table class="full-table"><thead><tr><th>实验与方法</th><th>有效运行数</th><th>指标均值</th><th>样本标准差</th><th>参考值对照</th></tr></thead><tbody>${r.experiments.flatMap(exp=>Object.entries(exp.variants||{}).map(([id,v])=>`<tr><td>${e(exp.experiment_id)} / ${e(id)}<br><span class="small-note">${e(r.plan?.experiments?.find(x=>x.id===exp.experiment_id)?.metric?.key||'指标键未提供')} · 原始数值</span></td><td class="num">${e(v.n)}</td><td class="num">${number(v.mean)}</td><td class="num">${number(v.sample_std)}</td><td>${e(verdicts[v.reference_comparison?.status]||'无参考值')}</td></tr>`)).join('')||'<tr><td colspan="5">尚无可汇总的实验结果。</td></tr>'}</tbody></table></div>${r.experiments.map(exp=>`<section class="statistical-acceptance"><h3>${e(exp.experiment_id)} · 配对统计验收</h3>${exp.fairness?`<p><strong>对照公平性：${exp.fairness.status==='verified'?'已核对':'证据不足'}</strong></p>${exp.fairness.reasons?.length?`<ul>${exp.fairness.reasons.map(x=>`<li>${e(x)}</li>`).join('')}</ul>`:''}`:''}${exp.comparisons?.map(c=>`<p><strong>${e(c.method)} / ${e(c.other)}：${e(verdicts[c.status]||c.status)}</strong><br>配对种子 ${c.paired_seeds.length} 个 · 方向统一后的差值区间 ${c.confidence_interval?c.confidence_interval.map(number).join(' 至 '):'证据不足，未计算'}<br><span class="small-note">家族置信水平 ${typeof c.family_confidence==='number'?(c.family_confidence*100).toFixed(1)+'%':'未提供'}；按预注册种子配对，区间已做多重比较校正。</span></p><details><summary>统计方法与原始依据</summary><p>${e(c.reason)}</p><p>${e(c.methodology)}</p></details>`).join('')||'<p>没有预注册的比较，不能据此判断主要结论。</p>'}</section>`).join('')}<details><summary>逐次运行与阶段证据</summary>${r.runs.map((row,ri)=>`<details class="evidence-attachment"><summary>${e(row.experiment)} / ${e(row.variant)} / seed ${row.seed} · ${reproductionStatuses[row.status]||e(row.status)}</summary><p>实际指标 ${number(row.metric)} · ${row.independent_metric?'已有独立重算记录':'未记录独立重算'}</p>${row.stages?.map((stage,si)=>`<details><summary>${e(stage.id)} · ${reproductionStatuses[stage.status]||e(stage.status)} · ${typeof stage.elapsed_seconds==='number'?stage.elapsed_seconds.toFixed(2):'未测'} 秒</summary><pre>${e(JSON.stringify(stage,null,2))}</pre></details>`).join('')||''}</details>`).join('')}</details><p class="assessment-boundary">主要结论${r.levels?.conclusion?'有验收记录':'尚未完成验收'}；报告只覆盖所声明计划。费用是声明单价下的估计，RSS 是子进程测量，未测资源保持未知。</p></div>`;}
 coverage(a,e){const c=a.coverage;if(!c)return '';return `<section class="reproduction-coverage"><h3>整篇论文的实验与主要结论</h3><p>${c.inventory_review?.complete?'已记录完整清单审核声明':'完整清单仍待审核'} · 审核人 ${e(c.inventory_review?.reviewer||'未提供')}</p><p class="small-note">从所有 PDF 页面提取的图表引用需要逐一归类。下表保留核心实验、正文引用、主要结论与实际执行计划的对应关系；语义对应仍依赖注明来源的人工审核。</p><div class="scroll-table"><table class="full-table"><thead><tr><th>论文实验</th><th>正文依据</th><th>主要结论</th><th>执行覆盖</th></tr></thead><tbody>${(c.experiments||[]).map(x=>`<tr><td>${e(x.id)}${x.core?' · 核心':''}</td><td>第 ${e(x.page)} 页<br>${e(x.quote)}</td><td>${(x.conclusion_ids||[]).map(e).join('、')||'未关联'}</td><td>${x.execution_ids.length?x.execution_ids.map(e).join('、'):'未覆盖'}</td></tr>`).join('')}</tbody></table></div><details><summary>主要结论、图表候选与审核依据</summary>${(c.conclusions||[]).map(x=>`<p><strong>${e(x.id)} · ${e(x.text)}</strong><br>第 ${e(x.page??'未知')} 页：${e(x.quote||'缺少原文依据')}</p>`).join('')}<p>全页图表候选：${(a.paper_candidates||[]).map(x=>e(x.id)+'（页 '+x.pages.join('、')+'）').join('；')||'未检测到编号引用，仍需人工通读'}</p><pre>${e(JSON.stringify({inventory_review:c.inventory_review,method_review:c.method_review,excluded_references:c.excluded_references},null,2))}</pre></details></section>`;}
 environmentEvidence(r,e){if(!r.executor&&!r.environment?.compatibility)return '';const external=r.measurement?.external,proof=r.environment?.compatibility,bytes=x=>typeof x==='number'&&Number.isFinite(x)?(x/1024**2).toFixed(1)+' MiB':'未测';return `<section class="runtime-environment-evidence"><h3>实际执行环境与独立采样</h3><p>执行器：${e(r.executor?.mode||r.mode)} · 镜像 ${e(r.environment?.image||'未构建')}<br>镜像内版本核对：${proof?.status==='verified'?'符合预注册要求':proof?.status==='failed'?'与要求矛盾':'缺少期望或测量'}</p><dl class="evaluation-facts"><div><dt>容器外内存采样峰值</dt><dd>${bytes(external?.sampled_peak_container_memory_bytes)}</dd></div><div><dt>有容器采样的阶段</dt><dd>${external?.sampled_container_stages??'未测'}</dd></div><div><dt>项目输出采样峰值</dt><dd>${bytes(r.measurement?.project_output_sampling?.sampled_peak_output_bytes)}</dd></div></dl><p class="small-note">采样可能遗漏短时峰值；容器统计与子进程 RSS 的测量范围不同。执行器来自实际 Docker daemon；浏览器上传的服务器说明不替代本次执行身份。</p><details><summary>版本、资源要求与费用范围的原始依据</summary><pre>${e(JSON.stringify({executor:r.executor,compatibility:proof,measurement:r.measurement,cost:r.cost},null,2))}</pre></details></section>`;}
 levels(r,e){return `<section class="reproduction-levels"><h3>复现验收层级</h3><dl class="evaluation-facts">${[['run','计划执行'],['environment_rebuilt','环境重建'],['training','论文训练协议'],['conclusion','主要结论']].map(([id,label])=>`<div><dt>${label}</dt><dd>${r.levels?.[id]?'证据满足':'尚未满足'}</dd></div>`).join('')}</dl>${['training','conclusion'].map(id=>Array.isArray(r.level_requirements?.[id])&&r.level_requirements[id].length?`<details><summary>${id==='training'?'训练协议':'主要结论'}仍缺少的证据（${r.level_requirements[id].length} 项）</summary><ul>${r.level_requirements[id].map(x=>`<li>${e(x)}</li>`).join('')}</ul></details>`:'').join('')}</section>`;}
 async loadPublicCase(){this.caseReport=validateReproductionReport(await (await fetch('./samples/liblinear-reproduction.json')).json());return this.caseReport;}
 async refresh(p){const s=reproductionState(p);if(!s.job||this.i.h.mode()!=='runtime')return;const id=s.job.id,binding={...s.binding},job=await this.i.h.request('/api/reproduction/runs/'+encodeURIComponent(id));const report=job.report_ready?validateReproductionReport(await this.i.h.request(job.report_url)):null;if(s.job?.id!==id||!sameIdentity(binding,identityOf(p)))return;if(report&&report.plan_sha256!==binding.plan_sha256)throw Error('返回报告的计划版本不匹配，已拒绝关联');s.job=job;s.report=report||s.report;s.source='runtime';await this.i.save(p);this.i.h.render();}
 async loadRegistry(){if(this.i.h.mode()!=='runtime')return;try{this.registry=(await this.i.h.request('/api/reproduction/runs')).items.sort((a,b)=>String(b.created_at).localeCompare(a.created_at));this.registryError='';}catch(error){this.registryError=error.message;}}
 async selectRegistry(id){const job=await this.i.h.request('/api/reproduction/runs/'+encodeURIComponent(id));const report=job.report_ready?validateReproductionReport(await this.i.h.request(job.report_url)):null;if(report&&report.plan_sha256!==job.plan_sha256)throw Error('报告计划与任务不一致');this.registrySelection={job,report,source:'runtime'};this.registryCase=null;this.registryPage=null;}
 registryView(page){const e=x=>this.i.esc(x),s=this.registrySelection;const tab=page==='trace'?'trace':page==='evidence'?'evidence':'overview';if(this.registryCase){if(this.registryPage!==page){this.review.context(this.registryCase,{source:'public_case'}).view.tab=tab;this.registryPage=page;}return `<section><div class="case-navigation"><span>独立公开案例 · CI 归档</span><button class="btn text" data-full-registry-case>返回任务列表</button></div>${this.report(this.registryCase,{source:'public_case'},null,e)}</section>`;}if(s?.report&&this.registryPage!==page){this.review.context(s.report,s).view.tab=tab;this.registryPage=page;}return `<div class="registry-toolbar"><div><h2>完整实验记录</h2><p class="small-note">本机任务可跨项目查询；打开记录不会把它绑定到当前论文。</p></div><button class="btn" data-full-registry-refresh>刷新本机记录</button></div>${this.registryError?`<p class="error-box">${e(this.registryError)}</p>`:''}<div class="field"><label for="full-run-select">选择实验任务</label><select id="full-run-select" data-full-registry-select><option value="">选择一个完整实验任务</option>${this.registry.map(x=>`<option value="${e(x.id)}" ${s?.job?.id===x.id?'selected':''}>${e(x.project_id||'独立运行')} · ${reproductionStatuses[x.status]} · ${e(x.id.slice(0,12))}</option>`).join('')}</select></div>${s?.report?this.report(s.report,s,reproductionSummary(s.report),e):s?.job?`<p class="info-strip">${reproductionStatuses[s.job.status]} · ${e(s.job.error||'报告尚未就绪，点击刷新读取最新状态。')}</p>`:`<section class="assessment-empty"><h3>尚未选择完整实验记录</h3><p>${this.i.h.mode()==='runtime'?'选择本机任务查看核验、指标与阶段证据。':'托管预览可查看公开 CPU 案例；实际执行连接本地工作台。'}</p><button class="btn" data-full-registry-case>查看 LIBLINEAR 公开案例</button></section>`}${this.registryCase?this.report(this.registryCase,{source:'public_case'},reproductionSummary(this.registryCase),e):''}`;}

 afterRender(){clearTimeout(this.timer);const p=this.i.current(),s=reproductionState(p);if(this.i.h.page()==='project'&&['reproduction','report'].includes(this.i.step)&&s.job&&['queued','running'].includes(s.job.status)&&this.i.h.mode()==='runtime'&&!document.querySelector('.review-station details[open],.review-decision:focus-within'))this.timer=setTimeout(()=>{if(this.i.current().id===p.id&&['reproduction','report'].includes(this.i.step))this.refresh(p).catch(error=>{this.error=error.message;this.i.h.render();});},3000);}
 bind(){this.review.bind();this.materials.bindEvents();this.bindWorkflow();document.addEventListener('toggle',event=>{if(event.target.closest?.('.review-station'))this.afterRender();},true);document.addEventListener('focusout',event=>{if(event.target.closest?.('.review-decision'))setTimeout(()=>this.afterRender(),0);});document.addEventListener('input',event=>{if(!event.target.hasAttribute('data-reproduction-plan'))return;const s=reproductionState(this.i.current());archiveExecution(s,'本地计划路径已改变');s.plan_path=event.target.value;s.audit=null;s.stale=true;this.i.save();});document.addEventListener('change',async event=>{if(!event.target.hasAttribute('data-reproduction-report')||!event.target.files?.[0])return;try{const file=event.target.files[0];if(file.size>10*1024**2)throw Error('报告最大 10 MB');const p=this.i.current(),s=reproductionState(p);const {report,reviews}=parseEvidenceArchive(JSON.parse(await file.text()));s.history??=[];s.history.unshift({id:report.run_id||crypto.randomUUID(),report,reviews,source:'uploaded',reason:'外部归档，未绑定当前材料',archived_at:new Date().toISOString()});this.panel='history';await this.i.save(p);this.i.h.render();}catch(error){this.error=error.message;this.i.h.render();}});document.addEventListener('click',async event=>{const dimension=event.target.closest('[data-reproduction-dimension]');if(dimension){this.dimension=dimension.dataset.reproductionDimension;this.i.h.render();return;}const button=event.target.closest('[data-reproduction]');if(!button)return;const p=this.i.current(),s=reproductionState(p);this.error='';this.busy=true;try{switch(button.dataset.reproduction){case'public-case':this.catalogCase=await this.loadPublicCase();this.caseReport=null;if(this.openExecution)await this.openExecution('case:liblinear');else this.i.h.navigate('workbench');break;case'export-case':this.i.h.download('liblinear-cpu-evidence.json',JSON.stringify(this.caseReport,null,2));break;case'audit':{const identity=identityOf(p),path=s.plan_path;const audit=await this.i.h.request('/api/reproduction/audit',{plan_path:s.plan_path,paper_sha256:p.paper?.sha256,project_id:p.id,archive_sha256:p.repository?.kind==='zip'?p.repository.sha256:undefined,material_bundle_id:s.material_bundle?.status==='bound'&&!s.bundle_stale&&s.plan_path===s.material_bundle.plan_path?s.material_bundle.id:undefined,imported_snapshot:p.repository?.kind==='github'?p.repository:undefined});if(path!==s.plan_path||!sameIdentity(identity,identityOf(p)))throw Error('核验期间材料发生变化，请重试');if(s.binding?.plan_sha256!==audit.plan_sha256)archiveExecution(s,'计划核验版本已变化');s.audit=audit;s.stale=false;this.panel='check';break;}case'start':{const reason=startBlocker(s,this.i.h.mode());if(reason)throw Error(reason);if(s.confirmed_plan!==s.audit.plan_sha256)throw Error('先确认本次计划的实际执行配置');const binding=identityOf(p);const job=await this.i.h.request('/api/reproduction/runs',{audit_token:s.audit.audit_token});if(!sameIdentity(binding,identityOf(p)))throw Error('提交期间材料变化，任务保留在执行记录中');archiveExecution(s,'已启动新的完整实验');s.binding=binding;s.job=job;s.report=null;s.source='runtime';this.panel='history';break;}case'refresh':await this.refresh(p);break;case'cancel':await this.i.h.request('/api/reproduction/runs/'+encodeURIComponent(s.job.id)+'/cancel',{});break;case'export-audit':this.i.h.download('reproduction-audit.json',JSON.stringify(s.audit,(k,v)=>k==='audit_token'?undefined:v,2));break;case'export-report':this.i.h.download('reproduction-report.json',JSON.stringify(s.report,null,2));break;}await this.i.save(p);}catch(error){this.error=error.message;}finally{this.busy=false;this.i.h.render();}});}
 bindWorkflow(){document.addEventListener('change',async event=>{const p=this.i.current(),s=reproductionState(p);if(event.target.matches('[data-execution-confirm]')){s.confirmed_plan=event.target.checked?s.audit?.plan_sha256:null;this.i.h.render();}if(event.target.matches('[data-full-registry-select]')){try{if(event.target.value)await this.selectRegistry(event.target.value);else this.registrySelection=null;}catch(error){this.registryError=error.message;}this.i.h.render();}});document.addEventListener('click',async event=>{const el=event.target.closest('[data-full-panel],[data-full-registry-refresh],[data-full-registry-case],[data-history-refresh]');if(!el)return;try{if(el.dataset.fullPanel)this.panel=el.dataset.fullPanel;if(el.hasAttribute('data-full-registry-refresh')){await this.loadRegistry();if(this.registrySelection)await this.selectRegistry(this.registrySelection.job.id);}if(el.hasAttribute('data-full-registry-case')){this.registryPage=null;this.registryCase=this.registryCase?null:validateReproductionReport(await (await fetch('./samples/liblinear-reproduction.json')).json());this.registrySelection=null;}if(el.hasAttribute('data-history-refresh')){const p=this.i.current(),entry=reproductionState(p).history[Number(el.dataset.historyRefresh)];const job=await this.i.h.request('/api/reproduction/runs/'+entry.job.id);entry.job=job;if(job.report_ready)entry.report=validateReproductionReport(await this.i.h.request(job.report_url));await this.i.save(p);}}catch(error){this.error=error.message;this.registryError=error.message;}this.i.h.render();});}

}
